fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Assumptions per problem statement:
    // - a.len() == b.len()
    // - all chars are '0' or '1'
    let n = a.len();
    let mut out = Vec::with_capacity(n);

    for i in 0..n {
        if a[i] == b[i] {
            out.push('0');
        } else {
            out.push('1');
        }
    }

    out
}